package com.vaibhav.ediflow.order.rules;
import com.vaibhav.ediflow.events.DocumentType; import org.springframework.stereotype.Component; import java.math.BigDecimal;
@Component public class InvoiceMatchRule implements BusinessRule {private static final BigDecimal TOLERANCE=new BigDecimal("0.01");public RuleResult evaluate(RuleContext c){if(c.event().documentType()!=DocumentType.INVOICE_810)return RuleResult.pass();if(c.referencedOrder()==null)return RuleResult.matchException("Referenced purchase order was not found.");BigDecimal difference=c.event().payload().totalAmount().subtract(c.referencedOrder().getTotalAmount()).abs();return difference.compareTo(TOLERANCE)<=0?RuleResult.pass():RuleResult.matchException("Invoice total differs from purchase order total by "+difference.setScale(2)+".");}public int order(){return 40;}}
